                    </button>
                </div>
                <p className="text-sm text-gray-400">Dica: Verifique se você está com internet e se não há extensões de bloqueio de anúncios interferindo na conexão.</p>
            </div>
        );
    }

    if (isAdminMode && (adminLeague || adminClub)) {
