  const handleUpdatePlayer = async (clubId: string, updatedPlayer: Player) => {
     try {
      const upperCasePlayer = { ...updatedPlayer, name: updatedPlayer.name.toUpperCase() };
      await leagueService.updatePlayer(updatedPlayer);
      await fetchData();
