  };

  return (
    <div className="bg-gray-900 text-gray-200 min-h-screen font-sans">
      <Header
        onTitleClick={() => {
          if (isAdminMode) {
              handleLogout();
          } else {
             setView({ name: 'home' });
          }
        }}
