import React, { useState, useEffect } from 'react';
import { Post, UserProfile, League } from '../types';
import * as leagueService from '../services/leagueService';

interface NewsFeedProps {
    league: League;
    user: UserProfile;
    isPaid: boolean;
}

const NewsFeed: React.FC<NewsFeedProps> = ({ league, user, isPaid }) => {
    const [posts, setPosts] = useState<Post[]>([]);
    const [content, setContent] = useState('');
    const [mediaType, setMediaType] = useState<'image' | 'video'>('image');
    const [mediaUrl, setMediaUrl] = useState('');
    const [isPosting, setIsPosting] = useState(false);
    const [uploadingFile, setUploadingFile] = useState<File | null>(null);

    useEffect(() => {
        loadPosts();
    }, [league.id]);

    const loadPosts = async () => {
        const data = await leagueService.fetchPosts(league.id);
        setPosts(data);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setUploadingFile(e.target.files[0]);
        }
    };

    const extractYoutubeId = (url: string) => {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!content.trim() && !uploadingFile && !mediaUrl) return;

        setIsPosting(true);
        try {
            let finalMediaUrl = mediaUrl;

            if (mediaType === 'image' && uploadingFile) {
                finalMediaUrl = await leagueService.uploadImage(uploadingFile);
            } else if (mediaType === 'video' && mediaUrl) {
                const ytId = extractYoutubeId(mediaUrl);
                if (!ytId) {
                    alert('Por favor, insira um link válido do YouTube.');
                    setIsPosting(false);
                    return;
                }
                finalMediaUrl = ytId;
            }

            await leagueService.createPost({
                user_id: user.id,
                user_name: user.full_name,
                user_photo: user.photo_url,
                league_id: league.id,
                content,
                media_url: finalMediaUrl,
                media_type: mediaType,
                is_official: false
            });

            setContent('');
            setMediaUrl('');
            setUploadingFile(null);
            loadPosts();
        } catch (error) {
            alert('Erro ao publicar. Tente novamente.');
        } finally {
            setIsPosting(false);
        }
    };

    return (
        <div className="max-w-2xl mx-auto space-y-6">
            {/* Post Creator */}
            <div className="bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg">
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="flex gap-3">
                        <img src={user.photo_url || `https://ui-avatars.com/api/?name=${user.full_name}`} className="w-10 h-10 rounded-full border border-gray-600" alt="User" />
                        <textarea 
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            placeholder="O que está acontecendo na liga?"
                            className="w-full bg-gray-900 border-none rounded-xl p-3 text-white focus:ring-2 focus:ring-green-500 resize-none h-24"
                        />
                    </div>

                    <div className="flex flex-wrap items-center justify-between gap-4 border-t border-gray-700 pt-3">
                        <div className="flex gap-2">
                            <button 
                                type="button" 
                                onClick={() => setMediaType('image')}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${mediaType === 'image' ? 'bg-green-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                Foto
                            </button>
                            <button 
                                type="button" 
                                onClick={() => setMediaType('video')}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${mediaType === 'video' ? 'bg-red-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 4-8 4z"/></svg>
                                YouTube
                            </button>
                        </div>

                        <div className="flex-grow">
                            {mediaType === 'image' ? (
                                <input type="file" onChange={handleFileChange} accept="image/*" className="text-xs text-gray-500 w-full" />
                            ) : (
                                <input 
                                    type="text" 
                                    placeholder="Cole o link do seu vídeo no YouTube..." 
                                    value={mediaUrl}
                                    onChange={(e) => setMediaUrl(e.target.value)}
                                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-1.5 text-xs text-white"
                                />
                            )}
                        </div>

                        <button 
                            disabled={isPosting}
                            className="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-6 rounded-full text-sm shadow-lg shadow-green-500/20 disabled:opacity-50 transition-all"
                        >
                            {isPosting ? 'Publicando...' : 'Postar'}
                        </button>
                    </div>
                    {mediaType === 'video' && (
                        <div className="bg-red-600/10 p-2 rounded-lg flex items-start gap-2 border border-red-600/20">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-red-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                            <p className="text-[10px] text-gray-400">
                                <strong>Obrigatório:</strong> Os vídeos devem ser publicados primeiro no seu canal do YouTube. 
                                <a href="https://www.youtube.com/create_channel" target="_blank" rel="noreferrer" className="text-red-400 hover:underline ml-1 font-bold">Não tem canal? Clique aqui para criar um agora.</a>
                            </p>
                        </div>
                    )}
                </form>
            </div>

            {/* Posts List */}
            <div className="space-y-4">
                {posts.map(post => (
                    <div key={post.id} className="bg-gray-800 rounded-xl border border-gray-700 overflow-hidden animate-fade-in-up">
                        <div className="p-4 flex items-center gap-3">
                            <img src={post.user_photo || `https://ui-avatars.com/api/?name=${post.user_name}`} className="w-10 h-10 rounded-full border border-gray-600" alt={post.user_name} />
                            <div>
                                <div className="flex items-center gap-2">
                                    <h4 className="font-bold text-white text-sm">{post.user_name}</h4>
                                    {post.is_official && <span className="bg-green-500/20 text-green-400 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-tighter">Admin</span>}
                                    {isPaid && <span className="text-yellow-400 text-[10px] border border-yellow-400/30 px-2 py-0.5 rounded-full font-bold uppercase">Torcedor Oficial</span>}
                                </div>
                                <p className="text-[10px] text-gray-500">{new Date(post.created_at).toLocaleString('pt-BR')}</p>
                            </div>
                        </div>

                        <div className="px-4 pb-4">
                            <p className="text-gray-200 text-sm whitespace-pre-wrap">{post.content}</p>
                        </div>

                        {post.media_url && (
                            <div className="bg-black aspect-video flex items-center justify-center">
                                {post.media_type === 'image' ? (
                                    <img src={post.media_url} className="max-h-[500px] w-full object-contain" alt="Post" />
                                ) : (
                                    <iframe 
                                        width="100%" 
                                        height="100%" 
                                        src={`https://www.youtube.com/embed/${post.media_url}`} 
                                        title="YouTube video player" 
                                        frameBorder="0" 
                                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                                        allowFullScreen
                                    ></iframe>
                                )}
                            </div>
                        )}

                        <div className="p-3 border-t border-gray-700 flex items-center gap-6">
                             <button className="flex items-center gap-2 text-gray-400 hover:text-red-400 transition-colors">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                                <span className="text-xs font-bold">Resenhar</span>
                             </button>
                             <button className="flex items-center gap-2 text-gray-400 hover:text-blue-400 transition-colors">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 100-3.316 3 3 0 000 3.316m0 0a3 3 0 100 3.316 3 3 0 000-3.316" /></svg>
                                <span className="text-xs font-bold">Enviar</span>
                             </button>
                        </div>
                    </div>
                ))}

                {posts.length === 0 && (
                    <div className="text-center py-20 text-gray-500">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-4 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a1.994 1.994 0 01-1.414-.586m0 0L11 14h4a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2v4l.586-.586z" /></svg>
                        Ninguém começou a resenha ainda. Seja o primeiro!
                    </div>
                )}
            </div>
        </div>
    );
};

export default NewsFeed;

import React, { useState, useEffect, useMemo } from 'react';
import { League } from '../types';

interface IBGEState {
  id: number;
  sigla: string;
  nome: string;
}

interface IBGECity {
  id: number;
  nome: string;
}

interface HomePageProps {
  leagues: League[];
  onSelectLeague: (league: League) => void;
}

const StarIcon: React.FC<{className?: string}> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 ${className}`} viewBox="0 0 20 20" fill="currentColor">
        <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
    </svg>
);


const HomePage: React.FC<HomePageProps> = ({ leagues, onSelectLeague }) => {
  const [states, setStates] = useState<IBGEState[]>([]);
  const [cities, setCities] = useState<IBGECity[]>([]);
  const [selectedState, setSelectedState] = useState('');
  const [selectedCity, setSelectedCity] = useState('');
  const [favoriteLeagueId, setFavoriteLeagueId] = useState<string | null>(null);

  useEffect(() => {
    fetch('https://servicodados.ibge.gov.br/api/v1/localidades/estados?orderBy=nome')
      .then(res => res.json())
      .then(setStates);
    setFavoriteLeagueId(localStorage.getItem('favoriteLeagueId'));
  }, []);

  useEffect(() => {
    if (selectedState) {
      fetch(`https://servicodados.ibge.gov.br/api/v1/localidades/estados/${selectedState}/municipios`)
        .then(res => res.json())
        .then(setCities);
    } else {
      setCities([]);
    }
    setSelectedCity('');
  }, [selectedState]);

  const filteredLeagues = useMemo(() => {
    let sortedLeagues = [...leagues];
    if (favoriteLeagueId) {
        const favoriteIndex = sortedLeagues.findIndex(l => l.id === favoriteLeagueId);
        if (favoriteIndex > -1) {
            const [favoriteLeague] = sortedLeagues.splice(favoriteIndex, 1);
            sortedLeagues.unshift(favoriteLeague);
        }
    }

    return sortedLeagues.filter(league => {
      const stateMatch = !selectedState || league.state === selectedState;
      const cityMatch = !selectedCity || league.city === selectedCity;
      return stateMatch && cityMatch;
    });
  }, [leagues, selectedState, selectedCity, favoriteLeagueId]);

  return (
    <div className="animate-fade-in">
      <div className="text-center mb-12">
        <h1 className="text-4xl md:text-5xl font-extrabold text-green-400">LigaFull</h1>
        <p className="text-white text-xl font-bold italic mt-1 mb-4 tracking-wider">é bola na rede!</p>
        <p className="mt-2 text-lg text-gray-300">A maior plataforma de gerenciamento social do futebol amador.</p>
        <p className="mt-2 text-md text-gray-400 italic">Explore ligas, veja a resenha e participe da comunidade.</p>
      </div>

      <div className="max-w-4xl mx-auto mb-8 p-4 bg-gray-800/50 rounded-lg">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                  <label htmlFor="state-filter" className="block text-sm font-medium text-gray-300 mb-1">Filtrar por Estado</label>
                  <select
                      id="state-filter"
                      value={selectedState}
                      onChange={(e) => setSelectedState(e.target.value)}
                      className="w-full bg-gray-700 border border-gray-600 rounded-md py-2 px-3 text-white"
                  >
                      <option value="">Todos os Estados</option>
                      {states.map(state => <option key={state.id} value={state.sigla}>{state.nome}</option>)}
                  </select>
              </div>
              <div>
                  <label htmlFor="city-filter" className="block text-sm font-medium text-gray-300 mb-1">Filtrar por Cidade</label>
                  <select
                      id="city-filter"
                      value={selectedCity}
                      onChange={(e) => setSelectedCity(e.target.value)}
                      disabled={!selectedState}
                      className="w-full bg-gray-700 border border-gray-600 rounded-md py-2 px-3 text-white disabled:opacity-50"
                  >
                      <option value="">Todos as Cidades</option>
                      {cities.map(city => <option key={city.id} value={city.nome}>{city.nome}</option>)}
                  </select>
              </div>
          </div>
      </div>


      <div className="space-y-6 max-w-4xl mx-auto">
        {filteredLeagues.length === 0 ? (
          <div className="text-center py-10 px-6 bg-gray-800 rounded-lg">
            <h3 className="text-xl font-semibold text-white">Nenhuma liga encontrada.</h3>
            <p className="text-gray-400 mt-2">
              Tente remover os filtros ou crie uma nova liga clicando no ícone de engrenagem no canto superior direito.
            </p>
          </div>
        ) : (
          filteredLeagues.map(league => (
            <div 
              key={league.id} 
              className="bg-gray-800 rounded-lg shadow-lg overflow-hidden cursor-pointer group flex items-center transition-all duration-300 hover:bg-gray-700 hover:shadow-xl border border-transparent hover:border-green-500/30"
              onClick={() => onSelectLeague(league)}
            >
              <img src={league.logoUrl} alt={`${league.name} logo`} className="w-24 h-24 sm:w-32 sm:h-32 object-cover flex-shrink-0" />
              <div className="p-4 sm:p-6">
                <h2 className="text-xl sm:text-2xl font-bold text-white group-hover:text-green-400 transition-colors duration-300 flex items-center gap-2">
                    {league.name}
                    {league.id === favoriteLeagueId && <StarIcon className="text-yellow-400" />}
                </h2>
                <div className="flex items-center gap-4 mt-2 text-sm sm:text-base text-gray-400">
                    <span>{league.city}, {league.state}</span>
                    <span>&bull;</span>
                    <span>{league.championships.length} campeonato(s)</span>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default HomePage;

import React, { useState, useEffect } from 'react';
import { Post, UserProfile, League } from '../types';
import * as leagueService from '../services/leagueService';

interface NewsFeedProps {
    league: League;
    user: UserProfile;
    isPaid: boolean;
}

const NewsFeed: React.FC<NewsFeedProps> = ({ league, user, isPaid }) => {
    const [posts, setPosts] = useState<Post[]>([]);
    const [content, setContent] = useState('');
    const [mediaType, setMediaType] = useState<'image' | 'video'>('image');
    const [mediaUrl, setMediaUrl] = useState('');
    const [isPosting, setIsPosting] = useState(false);
    const [uploadingFile, setUploadingFile] = useState<File | null>(null);

    useEffect(() => {
        loadPosts();
    }, [league.id]);

    const loadPosts = async () => {
        const data = await leagueService.fetchPosts(league.id);
        setPosts(data);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setUploadingFile(e.target.files[0]);
        }
    };

    const extractYoutubeId = (url: string) => {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!content.trim() && !uploadingFile && !mediaUrl) return;

        setIsPosting(true);
        try {
            let finalMediaUrl = mediaUrl;

            if (mediaType === 'image' && uploadingFile) {
                finalMediaUrl = await leagueService.uploadImage(uploadingFile);
            } else if (mediaType === 'video' && mediaUrl) {
                const ytId = extractYoutubeId(mediaUrl);
                if (!ytId) {
                    alert('Por favor, insira um link válido do YouTube.');
                    setIsPosting(false);
                    return;
                }
                finalMediaUrl = ytId;
            }

            await leagueService.createPost({
                user_id: user.id,
                user_name: user.full_name,
                user_photo: user.photo_url,
                league_id: league.id,
                content,
                media_url: finalMediaUrl,
                media_type: mediaType,
                is_official: false
            });

            setContent('');
            setMediaUrl('');
            setUploadingFile(null);
            loadPosts();
        } catch (error) {
            alert('Erro ao publicar. Tente novamente.');
        } finally {
            setIsPosting(false);
        }
    };

    return (
        <div className="max-w-2xl mx-auto space-y-6">
            {/* Slogan & Hero */}
            <div className="text-center py-4 bg-gradient-to-r from-green-600/20 to-transparent rounded-xl border border-green-500/30">
                <h3 className="text-xl font-black text-white italic tracking-tighter">LigaFull: é bola na rede! ⚽</h3>
                <p className="text-[10px] text-green-400 uppercase font-bold tracking-widest">A resenha oficial do {league.name}</p>
            </div>

            {/* Official Channel Promo */}
            <div className="bg-red-600/10 border border-red-600/20 rounded-xl p-3 flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="bg-red-600 p-2 rounded-lg">
                        <svg className="w-5 h-5 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 4-8 4z"/></svg>
                    </div>
                    <div>
                        <h4 className="text-xs font-bold text-white uppercase">Canal Oficial LigaFull</h4>
                        <p className="text-[10px] text-gray-400">Assista aos melhores momentos e transmissões ao vivo.</p>
                    </div>
                </div>
                <a href="https://youtube.com/@ligafull" target="_blank" rel="noreferrer" className="bg-red-600 hover:bg-red-700 text-white text-[10px] font-bold py-1.5 px-3 rounded-full transition-colors">INSCREVER-SE</a>
            </div>

            {/* Post Creator */}
            <div className="bg-gray-800 rounded-xl p-4 border border-gray-700 shadow-lg">
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="flex gap-3">
                        <img src={user.photo_url || `https://ui-avatars.com/api/?name=${user.full_name}`} className="w-10 h-10 rounded-full border border-gray-600" alt="User" />
                        <textarea 
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                            placeholder="O que está acontecendo na rodada?"
                            className="w-full bg-gray-900 border-none rounded-xl p-3 text-white focus:ring-2 focus:ring-green-500 resize-none h-24"
                        />
                    </div>

                    <div className="flex flex-wrap items-center justify-between gap-4 border-t border-gray-700 pt-3">
                        <div className="flex gap-2">
                            <button 
                                type="button" 
                                onClick={() => setMediaType('image')}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${mediaType === 'image' ? 'bg-green-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                Foto
                            </button>
                            <button 
                                type="button" 
                                onClick={() => setMediaType('video')}
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${mediaType === 'video' ? 'bg-red-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 4-8 4z"/></svg>
                                YouTube
                            </button>
                        </div>

                        <div className="flex-grow">
                            {mediaType === 'image' ? (
                                <input type="file" onChange={handleFileChange} accept="image/*" className="text-xs text-gray-500 w-full" />
                            ) : (
                                <input 
                                    type="text" 
                                    placeholder="Cole o link do vídeo do YouTube..." 
                                    value={mediaUrl}
                                    onChange={(e) => setMediaUrl(e.target.value)}
                                    className="w-full bg-gray-900 border border-gray-700 rounded-lg p-1.5 text-xs text-white"
                                />
                            )}
                        </div>

                        <button 
                            disabled={isPosting}
                            className="bg-green-500 hover:bg-green-600 text-white font-bold py-2 px-6 rounded-full text-sm shadow-lg shadow-green-500/20 disabled:opacity-50 transition-all"
                        >
                            {isPosting ? 'Publicando...' : 'Postar'}
                        </button>
                    </div>
                    {mediaType === 'video' && (
                        <div className="bg-gray-900 p-2 rounded-lg flex items-start gap-2 border border-gray-700">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-blue-400 mt-0.5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                            <p className="text-[10px] text-gray-400">
                                <strong>Dica:</strong> Você pode postar links do seu próprio canal ou do canal oficial da Liga. Se não tiver onde subir o vídeo, mande para o Administrador da sua liga postar no YouTube oficial do <strong>LigaFull</strong>.
                            </p>
                        </div>
                    )}
                </form>
            </div>

            {/* Posts List */}
            <div className="space-y-4">
                {posts.map(post => (
                    <div key={post.id} className="bg-gray-800 rounded-xl border border-gray-700 overflow-hidden animate-fade-in-up">
                        <div className="p-4 flex items-center gap-3">
                            <img src={post.user_photo || `https://ui-avatars.com/api/?name=${post.user_name}`} className="w-10 h-10 rounded-full border border-gray-600" alt={post.user_name} />
                            <div>
                                <div className="flex items-center gap-2">
                                    <h4 className="font-bold text-white text-sm">{post.user_name}</h4>
                                    {post.is_official && <span className="bg-green-500/20 text-green-400 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-tighter">Admin</span>}
                                    {isPaid && <span className="text-yellow-400 text-[10px] border border-yellow-400/30 px-2 py-0.5 rounded-full font-bold uppercase">Torcedor Oficial</span>}
                                </div>
                                <p className="text-[10px] text-gray-500">{new Date(post.created_at).toLocaleString('pt-BR')}</p>
                            </div>
                        </div>

                        <div className="px-4 pb-4">
                            <p className="text-gray-200 text-sm whitespace-pre-wrap">{post.content}</p>
                        </div>

                        {post.media_url && (
                            <div className="bg-black aspect-video flex items-center justify-center">
                                {post.media_type === 'image' ? (
                                    <img src={post.media_url} className="max-h-[500px] w-full object-contain" alt="Post" />
                                ) : (
                                    <iframe 
                                        width="100%" 
                                        height="100%" 
                                        src={`https://www.youtube.com/embed/${post.media_url}`} 
                                        title="YouTube video player" 
                                        frameBorder="0" 
                                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                                        allowFullScreen
                                    ></iframe>
                                )}
                            </div>
                        )}

                        <div className="p-3 border-t border-gray-700 flex items-center gap-6">
                             <button className="flex items-center gap-2 text-gray-400 hover:text-red-400 transition-colors">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" /></svg>
                                <span className="text-xs font-bold">Resenhar</span>
                             </button>
                             <button className="flex items-center gap-2 text-gray-400 hover:text-blue-400 transition-colors">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 100-3.316 3 3 0 000 3.316m0 0a3 3 0 100 3.316 3 3 0 000-3.316" /></svg>
                                <span className="text-xs font-bold">Enviar</span>
                             </button>
                        </div>
                    </div>
                ))}

                {posts.length === 0 && (
                    <div className="text-center py-20 text-gray-500">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-4 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a1.994 1.994 0 01-1.414-.586m0 0L11 14h4a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2v4l.586-.586z" /></svg>
                        Ninguém começou a resenha ainda. Seja o primeiro!
                    </div>
                )}
            </div>
        </div>
    );
