    const { data: n } = await supabase.from('clubs').insert({ id: crypto.randomUUID(), name, abbreviation: 'TBD' }).select().single();
    return { id: n.id, name: n.name, abbreviation: n.abbreviation, logoUrl: '', players: [], technicalStaff: [] };
};

