/**
 * YouTube Direct Upload Service
 * Nota: Em um ambiente de produção, o CLIENT_ID e SCOPES seriam configurados via ENV.
 * O usuário deve estar logado na conta do canal 'LigaFull' para que o upload seja direto.
 */

const CLIENT_ID = 'SUA_CLIENT_ID_DO_GOOGLE.apps.googleusercontent.com'; // O admin deve configurar isso no Google Cloud Console
const SCOPES = 'https://www.googleapis.com/auth/youtube.upload';

export interface UploadProgress {
    percentage: number;
    status: string;
}

export const uploadToYouTube = async (
    file: File, 
    title: string, 
    description: string,
    onProgress: (progress: UploadProgress) => void
): Promise<string> => {
    return new Promise((resolve, reject) => {
        const metadata = {
            snippet: {
                title: title,
                description: description,
                tags: ['LigaFull', 'Futebol Amador', 'Gols'],
                categoryId: '17' // Sports
            },
            status: {
                privacyStatus: 'public', // Define como público para aparecer no feed
                selfDeclaredMadeForKids: false
            }
        };

        const uploader = new (window as any).gapi.client.youtube.VideoUploader({
            file: file,
            metadata: metadata,
            onProgress: (data: any) => {
                const percentage = Math.round((data.loaded / data.total) * 100);
                onProgress({ percentage, status: 'Enviando para o YouTube...' });
            },
            onComplete: (data: string) => {
                const videoData = JSON.parse(data);
                resolve(videoData.id);
            },
            onError: (error: any) => {
                reject(error);
            }
        });

        uploader.upload();
    });
};

// Inicialização da API do Google
export const initYouTubeAPI = () => {
    return new Promise((resolve, reject) => {
        (window as any).gapi.load('client:auth2', () => {
            (window as any).gapi.client.init({
                clientId: CLIENT_ID,
                scope: SCOPES,
                discoveryDocs: ['https://www.googleapis.com/discovery/v1/apis/youtube/v3/rest']
            }).then(resolve).catch(reject);
        });
    });
};

