    active: boolean;
}

const generateSlug = (name: string) => {
  return name.toLowerCase().replace(/\s+/g, '-').replace(/[^\w-]+/g, '');
};

const resizeImage = (file: File, width: number, height: number): Promise<File> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = event => {
            if (!event.target?.result) return reject(new Error("Error reading file"));
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                canvas.width = width; canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) return reject(new Error('Canvas context error'));
                ctx.drawImage(img, 0, 0, width, height);
                canvas.toBlob((blob) => {
                    if (!blob) return reject(new Error('Blob error'));
                    resolve(new File([blob], file.name, { type: 'image/jpeg' }));
                }, 'image/jpeg', 0.9);
            };
        };
    });
};

export const uploadImage = async (file: File): Promise<string> => {
    if (!file) return '';
    const resizedFile = await resizeImage(file, 800, 800);
    const fileName = `${crypto.randomUUID()}.jpg`;
    const { error } = await supabase.storage.from('images').upload(fileName, resizedFile);
    if (error) return '';
    const { data } = supabase.storage.from('images').getPublicUrl(fileName);
    return data.publicUrl;
};

export const getOrCreateProfile = async (supabaseUser: User): Promise<UserProfile> => {
    const { data } = await supabase.from('profiles').select('*').eq('id', supabaseUser.id).single();
    if (data) return data;
    const newProfile = {
        id: supabaseUser.id,
        full_name: supabaseUser.user_metadata.full_name || supabaseUser.email?.split('@')[0],
        photo_url: supabaseUser.user_metadata.avatar_url,
        email: supabaseUser.email!,
        is_paid: true, // Sempre verdadeiro no novo modelo
        trial_started_at: new Date().toISOString(),
        registered_league_id: ''
    };
    const { data: inserted, error } = await supabase.from('profiles').insert(newProfile).select().single();
    if (error) throw error;
    return inserted;
};

export const fetchAds = async (): Promise<Ad[]> => {
    const { data, error } = await supabase.from('ads').select('*').eq('active', true);
    if (error) return [];
    return data;
};

export const fetchPosts = async (leagueId: string): Promise<Post[]> => {
    const { data, error } = await supabase.from('posts').select('*').eq('league_id', leagueId).order('created_at', { ascending: false });
    return data || [];
};

export const createPost = async (postData: Omit<Post, 'id' | 'created_at'>): Promise<Post> => {
    const { data, error } = await supabase.from('posts').insert({ ...postData, id: crypto.randomUUID() }).select().single();
    if (error) throw error;
    return data;
};

// ... restante dos métodos de liga e campeonatos (mantidos conforme arquivo original)
export const fetchLeagues = async (): Promise<League[]> => {
    const { data, error } = await supabase.from('leagues').select(`
        id, name, slug, logo_url, admin_email, admin_password_hash, city, state,
        officials (id, name, nickname, cpf, bank_account, type),
        championships (
            id, name, financials,
            championship_clubs (
                clubs (
                    id, name, abbreviation, logo_url, whatsapp,
                    players (id, name, position, goals_in_championship, photo_url, birth_date, nickname, cpf),
                    technical_staff (id, name, role)
                )
            ),
            matches (
                id, round, home_team_id, away_team_id, home_score, away_score, match_date, status, location,
                referee_id, assistant1_id, assistant2_id, table_official_id, home_lineup, away_lineup,
                match_events (type, player_id, minute)
            )
        )
    `);
    if (error) throw error;
    return transformLeagues(data || []);
};

const transformLeagues = (data: any[]): League[] => {
    return data.map(l => ({
        id: l.id, name: l.name, slug: l.slug, logoUrl: l.logo_url || '', adminEmail: l.admin_email, city: l.city || '', state: l.state || '',
        referees: (l.officials || []).filter((o: any) => o.type === 'referee').map((o: any) => ({ id: o.id, name: o.name, nickname: o.nickname, cpf: o.cpf, bankAccount: o.bank_account })),
        tableOfficials: (l.officials || []).filter((o: any) => o.type === 'table_official').map((o: any) => ({ id: o.id, name: o.name, nickname: o.nickname, cpf: o.cpf, bankAccount: o.bank_account })),
        championships: (l.championships || []).map((c: any) => ({
            id: c.id, name: c.name, standings: [], financials: c.financials,
            clubs: (c.championship_clubs || []).map((cc: any) => cc.clubs).filter(Boolean).map((club: any) => ({
                id: club.id, name: club.name, abbreviation: club.abbreviation, logoUrl: club.logo_url || '', whatsapp: club.whatsapp || '',
                players: (club.players || []).map((p: any) => ({ id: p.id, name: p.name, position: p.position, goals: p.goals_in_championship || 0, photoUrl: p.photo_url || '', birthDate: p.birth_date || '', nickname: p.nickname || '', cpf: p.cpf || '' })),
                technicalStaff: (club.technical_staff || []).map((ts: any) => ({ id: ts.id, name: ts.name, role: ts.role }))
            })),
            matches: (c.matches || []).map((m: any) => ({
                id: m.id, round: m.round, homeScore: m.home_score, awayScore: m.away_score, date: m.match_date, status: m.status, location: m.location || 'A definir',
                homeTeam: { id: m.home_team_id, name: '', abbreviation: '', logoUrl: '', players: [], technicalStaff: [] },
                awayTeam: { id: m.away_team_id, name: '', abbreviation: '', logoUrl: '', players: [], technicalStaff: [] },
                events: (m.match_events || []).map((e: any) => ({ type: e.type, playerId: e.player_id, playerName: '', minute: e.minute })),
                homeLineup: m.home_lineup || [], awayLineup: m.away_lineup || []
            }))
        }))
    }));
};

