  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    localStorage.removeItem('ligafull_guest_user');
    setIsAdminMode(false);
    setAdminLeague(null);
    setAdminClub(null);
    setUser(null);
    setView({ name: 'home' });
    setIsAdminActionsModalOpen(false);
  };

  const renderContent = () => {
    if (isLoading) return <div className="text-center py-20 text-green-400">Carregando LigaFull...</div>;

    if (!user && !isAdminMode) {
        return <AuthWall onGuestLogin={handleGuestLogin} />;
    }

    if (isAdminMode && (adminLeague || adminClub)) {
        if (adminClub) {
            const { league, championship, club } = adminClub;
            const fullLeagueData = processedLeagues.find(l => l.id === league.id);
            const fullChampionshipData = fullLeagueData?.championships.find(c => c.id === championship.id);
            const fullClubData = fullChampionshipData?.clubs.find(c => c.id === club.id);
            if (view.name === 'club_admin' && fullLeagueData && fullChampionshipData && fullClubData) {
                return <ClubAdminPage league={fullLeagueData} championship={fullChampionshipData} club={fullClubData} onUpdatePlayer={() => {}} onCreatePlayer={() => {}} onDeletePlayer={() => {}} onCreateStaff={() => {}} onUpdateStaff={() => {}} onDeleteStaff={() => {}} onUpdateClubDetails={() => {}} />;
            }
        }
        if (adminLeague) {
            const adminLeagueData = processedLeagues.find(l => l.id === adminLeague.id);
            if (!adminLeagueData) { handleLogout(); return null; }
            switch (view.name) {
                case 'admin_league':
                    return <AdminLeaguePage league={adminLeagueData} onSelectChampionship={champ => setView({name: 'admin_championship', leagueId: adminLeagueData.id, championshipId: champ.id})} onCreateChampionship={() => {}} onCreateOfficial={() => {}} onUpdateOfficial={() => {}} onDeleteOfficial={() => {}} />;
                case 'admin_championship':
                    const adminChampionship = adminLeagueData.championships.find(c => c.id === view.championshipId);
                    if (adminChampionship) return <AdminChampionshipPage championship={adminChampionship} league={adminLeagueData} onBack={() => setView({name: 'admin_league', leagueId: adminLeagueData.id})} onSelectMatch={() => {}} onCreateClub={() => {}} onUpdateMatch={() => {}} onNavigateToCreateMatches={() => {}} onUpdatePlayer={() => {}} onCreatePlayer={() => {}} onDeletePlayer={() => {}} onCreateStaff={() => {}} onUpdateStaff={() => {}} onDeleteStaff={() => {}} onSaveFinancials={() => {}} onUpdateClubRegistrationStatus={() => {}} onUpdateClubFinePaymentStatus={() => {}} onUpdateClubDetails={() => {}} />;
                    break;
            }
        }
    }

    switch (view.name) {
        case 'home':
            return <HomePage leagues={processedLeagues} onSelectLeague={league => setView({ name: 'league', leagueId: league.id })} />;
        case 'league':
            if (currentLeague) return <LeaguePage league={currentLeague} onSelectChampionship={champ => setView({ name: 'championship', leagueId: currentLeague.id, championshipId: champ.id })} onBack={() => setView({ name: 'home' })} isAdminMode={false} user={user} onCreateChampionship={() => {}} />;
            break;
        case 'championship':
            if (currentChampionship && currentLeague) return <ChampionshipPage championship={currentChampionship} league={currentLeague} onBack={() => setView({ name: 'league', leagueId: currentLeague.id })} onSelectMatch={match => setView({ name: 'match', leagueId: currentLeague.id, championshipId: currentChampionship.id, matchId: match.id })} isAdminMode={false} user={user} onCreateClub={() => {}} onGenerateMatches={() => {}} />;
            break;
        case 'match':
            if (currentMatch && currentLeague && currentChampionship) return <MatchSummaryPage match={currentMatch} league={currentLeague} onBack={() => setView({ name: 'championship', leagueId: currentLeague.id, championshipId: currentChampionship.id })} />;
            break;
        case 'create_league':
            return <CreateLeaguePage onBack={() => setView({ name: 'home' })} onCreateLeague={() => {}} isLoading={isLoading} />;
    }
    return null;
  };

  return (
    <div className="bg-gray-900 text-gray-200 min-h-screen font-sans">
      <Header
        onTitleClick={() => isAdminMode ? handleLogout() : setView({ name: 'home' })}
        onAdminClick={() => isAdminMode ? setIsAdminActionsModalOpen(true) : setIsAdminModalOpen(true)}
        onMenuClick={() => setIsSidebarOpen(true)}
        isAdminMode={isAdminMode}
      />
      <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} leagues={processedLeagues} onSelectLeague={league => { setView({ name: 'league', leagueId: league.id }); setIsSidebarOpen(false); }} />
      <main className="container mx-auto px-4 py-8">
        {renderContent()}
      </main>
      <Footer />
      <AdminModal isOpen={isAdminModalOpen} onClose={() => setIsAdminModalOpen(false)} onNavigateToCreateLeague={() => { setIsAdminModalOpen(false); setView({ name: 'create_league' }); }} onLogin={handleLogin} />
      <AdminActionsModal isOpen={isAdminActionsModalOpen} onClose={() => setIsAdminActionsModalOpen(false)} onLogout={handleLogout} />
    </div>
  );
};

