      <div className="flex flex-col items-center mb-10 text-center">
        <div className="relative group mb-4">
            <div className="absolute inset-0 bg-green-500 rounded-full blur-2xl opacity-10 group-hover:opacity-20 transition-opacity"></div>
            <img src={league.logoUrl} alt={`${league.name} logo`} className="relative w-24 h-24 sm:w-32 sm:h-32 rounded-[40px] object-cover border-4 border-gray-800 shadow-2xl"/>
        </div>
        <h1 className="text-3xl sm:text-4xl font-black text-white tracking-tighter uppercase italic">{league.name}</h1>
