        <button 
            onClick={() => setActiveView('resenha')}
            className={`flex-1 py-3 px-4 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeView === 'resenha' ? 'bg-green-600 text-white shadow-lg shadow-green-600/20' : 'text-gray-500 hover:text-gray-300'}`}
        >
            Resenha ⚡
        </button>
        <button 
            onClick={() => setActiveView('campeonatos')}
            className={`flex-1 py-3 px-4 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeView === 'campeonatos' ? 'bg-green-600 text-white shadow-lg shadow-green-600/20' : 'text-gray-500 hover:text-gray-300'}`}
        >
            Campeonatos 🏆
        </button>
      </div>

      {/* Conteúdo Renderizado */}
      <div className="animate-fade-in-up">
        {activeView === 'resenha' ? (
            user ? (
                <NewsFeed league={league} user={user} />
            ) : (
                <div className="text-center py-20 bg-gray-800/20 rounded-[40px] border border-dashed border-white/5">
                    <p className="text-gray-500 font-bold uppercase tracking-widest">Carregando Feed...</p>
                </div>
            )
        ) : (
            <div className="space-y-6">
                <div className="flex justify-between items-center px-4">
                    <h2 className="text-xl font-black text-white tracking-tight uppercase italic">Nossos Campeonatos</h2>
                    {isAdminMode && (
                        <button 
                            onClick={() => setShowAddChampForm(!showAddChampForm)}
                            className="bg-green-600 hover:bg-green-700 text-white font-black py-2 px-6 rounded-xl text-[10px] uppercase tracking-tighter transition-all"
