                            Criar Novo
                        </button>
                    )}
                </div>

                {showAddChampForm && isAdminMode && (
                    <form onSubmit={handleAddChampionship} className="bg-gray-800 p-6 rounded-[32px] border border-white/5 animate-fade-in-down space-y-4">
                        <input 
                            type="text"
