                            className="w-full bg-black/50 border-none rounded-2xl py-4 px-6 text-white focus:ring-2 focus:ring-green-600"
                        />
                        <div className="flex justify-end gap-3">
                            <button type="button" onClick={() => setShowAddChampForm(false)} className="text-gray-500 font-bold text-xs uppercase">Cancelar</button>
                            <button type="submit" className="bg-green-600 hover:bg-green-700 text-white font-black py-2 px-6 rounded-xl text-xs uppercase">Salvar</button>
                        </div>
                    </form>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {league.championships.map(champ => (
                        <div 
                            key={champ.id} 
