                            <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-30 transition-opacity">
                                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className="text-green-500">
                                    <path d="M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z" fill="currentColor"/>
                                </svg>
                            </div>
                            <h3 className="text-2xl font-black text-white uppercase tracking-tighter italic group-hover:text-green-400 transition-colors">{champ.name}</h3>
                            <p className="text-gray-500 font-bold text-[10px] uppercase tracking-widest mt-2">{champ.clubs.length} Clubes Inscritos</p>
                            <div className="mt-6 flex items-center text-green-500 font-black text-[10px] uppercase tracking-widest gap-2">
                                Ver Tabela e Classificação
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                                </svg>
                            </div>
                        </div>
                    ))}
                    {league.championships.length === 0 && (
                        <div className="col-span-2 text-center py-20 bg-gray-800/10 rounded-[40px] border border-dashed border-white/5">
