import React, { useState, useEffect } from 'react';
import { Post, UserProfile, League } from '../types';
import * as leagueService from '../services/leagueService';
import * as youtubeService from '../services/youtubeService';

interface NewsFeedProps {
    league: League;
    user: UserProfile;
}

const AdBanner: React.FC<{ brand: string; imgUrl: string; targetUrl?: string }> = ({ brand, imgUrl, targetUrl }) => (
    <div 
        onClick={() => targetUrl && window.open(targetUrl, '_blank')}
        className="bg-gray-800/40 rounded-[24px] border border-white/5 p-4 mb-6 overflow-hidden relative group cursor-pointer shadow-lg transition-all hover:bg-gray-800/60"
    >
        <div className="flex items-center gap-4 relative z-10">
            <div className="w-16 h-16 flex-shrink-0 bg-white/5 rounded-xl p-2 flex items-center justify-center backdrop-blur-sm border border-white/5">
                <img src={imgUrl} className="max-w-full max-h-full object-contain" alt={brand} />
            </div>
            <div className="flex-grow">
                <div className="flex items-center gap-2 mb-1">
                    <span className="bg-green-500 text-black text-[7px] font-black px-1.5 py-0.5 rounded-full uppercase">Ad</span>
                    <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{brand}</span>
