);

const NewsFeed: React.FC<NewsFeedProps> = ({ league, user }) => {
    const [posts, setPosts] = useState<Post[]>([]);
    const [ads, setAds] = useState<any[]>([]);
    const [content, setContent] = useState('');
    const [mediaType, setMediaType] = useState<'image' | 'video'>('image');
    const [isPosting, setIsPosting] = useState(false);
    const [uploadProgress, setUploadProgress] = useState(0);
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [filePreview, setFilePreview] = useState<string>('');
    const [isExpanded, setIsExpanded] = useState(false);

    useEffect(() => {
        loadData();
        youtubeService.initGapi();
    }, [league.id]);

    const loadData = async () => {
        try {
            const [postsData, adsData] = await Promise.all([
                leagueService.fetchPosts(league.id),
                leagueService.fetchAds()
            ]);
            setPosts(postsData);
            setAds(adsData);
        } catch (error) {
            console.error('Erro ao carregar feed:', error);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setSelectedFile(file);
            setFilePreview(URL.createObjectURL(file));
            setIsExpanded(true);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!content.trim() && !selectedFile) return;

        setIsPosting(true);
        setUploadProgress(10);

        try {
            let mediaUrl = '';

            if (selectedFile) {
                if (mediaType === 'image') {
                    mediaUrl = await leagueService.uploadImage(selectedFile);
                    setUploadProgress(70);
                } else {
                    const videoTitle = `${league.name} - Lance de ${user.full_name}`;
                    const videoDesc = `${content}\n\nPostado via App LigaFull Digital!`;
                    try {
                        mediaUrl = await youtubeService.uploadDirectToYoutube(
                            selectedFile, 
                            { title: videoTitle, description: videoDesc },
                            (p) => setUploadProgress(p)
                        );
                    } catch (err: any) {
                        if (err.message === 'AUTH_REQUIRED') {
                            const googleAuth = (window as any).gapi.auth2.getAuthInstance();
                            await googleAuth.signIn();
                            setIsPosting(false);
                            return;
                        }
                        throw err;
                    }
                }
            }

            setUploadProgress(90);

            // Chamada ao serviço de criação de post
            const newPost = await leagueService.createPost({
                user_id: user.id,
                user_name: user.full_name,
                user_photo: user.photo_url || '',
                league_id: league.id,
                content: content.trim(),
                media_url: mediaUrl || undefined,
                media_type: selectedFile ? mediaType : undefined,
                is_official: false
            });

            console.log('Post criado com sucesso:', newPost);

            setUploadProgress(100);
            setContent('');
            setSelectedFile(null);
            setFilePreview('');
            setIsExpanded(false);
            loadData(); // Recarrega o feed
        } catch (error: any) {
            console.error('Erro detalhado ao criar post:', error);
            alert(`Erro ao publicar: ${error.message || 'Erro desconhecido'}`);
        } finally {
            setIsPosting(false);
            setUploadProgress(0);
        }
    };

    return (
        <div className="max-w-xl mx-auto space-y-4">
            {/* Criador de Post Estilo Facebook */}
            <div className="bg-gray-800 rounded-2xl p-4 border border-white/5 shadow-xl transition-all">
                <div className="flex gap-3">
                    <img src={user.photo_url || `https://ui-avatars.com/api/?name=${user.full_name}`} className="w-10 h-10 rounded-full border border-white/10" alt="User" />
                    {!isExpanded ? (
                        <button 
                            onClick={() => setIsExpanded(true)}
                            className="flex-grow bg-gray-700/50 hover:bg-gray-700 rounded-full px-5 py-2 text-left text-gray-400 text-sm font-medium transition-colors"
                        >
                            No que você está pensando, {user.full_name.split(' ')[0]}?
                        </button>
                    ) : (
                        <div className="flex-grow animate-fade-in">
                            <textarea 
                                value={content}
                                autoFocus
                                onChange={(e) => setContent(e.target.value)}
                                placeholder={`No que você está pensando, ${user.full_name.split(' ')[0]}?`}
                                className="w-full bg-transparent border-none p-0 text-white placeholder-gray-500 focus:ring-0 resize-none h-24 text-base font-medium"
                            />
                        </div>
                    )}
                </div>

                {isExpanded && (
                    <div className="mt-4 animate-fade-in-up">
                        {filePreview && (
                            <div className="relative rounded-2xl overflow-hidden border border-white/10 bg-black mb-4 group">
                                {mediaType === 'image' ? (
                                    <img src={filePreview} className="max-h-64 mx-auto object-contain" alt="Preview" />
                                ) : (
                                    <video src={filePreview} className="max-h-64 mx-auto" controls />
                                )}
                                <button type="button" onClick={() => {setSelectedFile(null); setFilePreview('');}} className="absolute top-2 right-2 bg-black/60 text-white p-2 rounded-full backdrop-blur-md">
