                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                    </svg>
                                    <span className="text-xs font-bold text-gray-400 group-hover:text-white transition-colors">Foto</span>
                                    <input type="file" className="hidden" accept="image/*" onChange={(e) => { setMediaType('image'); handleFileChange(e); }} />
                                </label>
                                <label className="cursor-pointer group flex items-center gap-2 px-3 py-2 rounded-xl hover:bg-white/5 transition-colors">
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                                    </svg>
                                    <span className="text-xs font-bold text-gray-400 group-hover:text-white transition-colors">Vídeo</span>
                                    <input type="file" className="hidden" accept="video/*" onChange={(e) => { setMediaType('video'); handleFileChange(e); }} />
                                </label>
                            </div>

                            <div className="flex gap-2">
                                <button type="button" onClick={() => setIsExpanded(false)} className="text-xs font-bold text-gray-500 px-4 py-2 hover:bg-white/5 rounded-xl">Cancelar</button>
                                <button 
                                    onClick={handleSubmit}
                                    disabled={isPosting || (!content.trim() && !selectedFile)}
                                    className="bg-green-600 hover:bg-green-700 disabled:bg-gray-700 disabled:text-gray-500 text-white font-black px-6 py-2 rounded-xl text-xs transition-all shadow-lg"
                                >
                                    {isPosting ? 'Publicando...' : 'Publicar'}
                                </button>
                            </div>
                        </div>

                        {isPosting && (
                            <div className="mt-3">
                                <div className="h-1 bg-gray-700 rounded-full overflow-hidden">
                                    <div className="h-full bg-green-500 transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Listagem de Posts Estilo Facebook */}
            <div className="space-y-4 pb-20">
                {posts.map((post, index) => (
                    <React.Fragment key={post.id}>
                        {/* AD Space Intercalado */}
                        {index > 0 && index % 4 === 0 && ads.length > 0 && (
                            <AdBanner 
                                brand={ads[index % ads.length].brand_name} 
                                imgUrl={ads[index % ads.length].image_url}
                                targetUrl={ads[index % ads.length].target_url}
                            />
                        )}

                        <div className="bg-gray-800 rounded-2xl border border-white/5 overflow-hidden animate-fade-in-up shadow-xl">
                            {/* Header do Post */}
                            <div className="p-4 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <img src={post.user_photo || `https://ui-avatars.com/api/?name=${post.user_name}`} className="w-10 h-10 rounded-full border border-white/10" alt={post.user_name} />
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <h4 className="font-bold text-white text-sm tracking-tight hover:underline cursor-pointer">{post.user_name}</h4>
                                            {post.is_official && <span className="bg-green-500/10 text-green-500 text-[8px] px-1.5 py-0.5 rounded-full font-black border border-green-500/20">OFICIAL</span>}
