export interface Ad {
    id: string;
    brand_name: string;
    image_url: string;
    target_url: string;
    active: boolean;
}

const resizeImage = (file: File, width: number, height: number): Promise<File> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = event => {
            if (!event.target?.result) return reject(new Error("Error reading file"));
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                canvas.width = width; canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) return reject(new Error('Canvas context error'));
                ctx.drawImage(img, 0, 0, width, height);
                canvas.toBlob((blob) => {
                    if (!blob) return reject(new Error('Blob error'));
                    resolve(new File([blob], file.name, { type: 'image/jpeg' }));
                }, 'image/jpeg', 0.9);
            };
        };
    });
};

export const uploadImage = async (file: File): Promise<string> => {
    if (!file) return '';
    try {
        const resizedFile = await resizeImage(file, 800, 800);
        const fileName = `${crypto.randomUUID()}.jpg`;
        const { error } = await supabase.storage.from('images').upload(fileName, resizedFile);
        if (error) {
            console.error('Erro no upload de imagem:', error);
            return '';
        }
        const { data } = supabase.storage.from('images').getPublicUrl(fileName);
        return data.publicUrl;
    } catch (err) {
        console.error('Erro ao processar imagem:', err);
        return '';
    }
};

export const getOrCreateProfile = async (supabaseUser: User): Promise<UserProfile> => {
    const { data } = await supabase.from('profiles').select('*').eq('id', supabaseUser.id).single();
    if (data) return data;
    const newProfile = {
        id: supabaseUser.id,
        full_name: supabaseUser.user_metadata.full_name || supabaseUser.email?.split('@')[0],
        photo_url: supabaseUser.user_metadata.avatar_url,
        email: supabaseUser.email!,
        is_paid: true,
        trial_started_at: new Date().toISOString(),
        registered_league_id: ''
    };
    const { data: inserted, error } = await supabase.from('profiles').insert(newProfile).select().single();
    if (error) throw error;
    return inserted;
};

