        throw new Error(`Erro no banco: ${error.message}`);
    }
    return data;
};

// Query sem cover_url, city e state para evitar erro 42703 (coluna inexistente)
const LEAGUE_SELECT_QUERY = `
    id, name, slug, logo_url, admin_email, admin_password_hash,
    officials (id, name, nickname, cpf, bank_account, type),
    championships (
        id, name, registration_fee_per_club, referee_fee, assistant_fee, table_official_fee, field_fee, yellow_card_fine, red_card_fine,
        championship_clubs (
            amount_paid,
            clubs (
                id, name, abbreviation, logo_url, whatsapp,
                players (id, name, position, goals_in_championship, photo_url, birth_date, nickname, cpf),
                technical_staff (id, name, role)
            )
        ),
        matches (
            id, round, home_team_id, away_team_id, home_score, away_score, match_date, status, location,
            referee_id, assistant1_id, assistant2_id, table_official_id,
            match_events (type, player_id, minute)
        )
    )
`;

export const login = async (email: string, pass: string): Promise<League | null> => {
    const { data, error } = await supabase.from('leagues').select(LEAGUE_SELECT_QUERY)
        .eq('admin_email', email).eq('admin_password_hash', pass).maybeSingle();

    if (error || !data) return null;
    return transformLeagues([data])[0];
};

export const fetchLeagues = async (): Promise<League[]> => {
    try {
        const { data, error } = await supabase.from('leagues').select(LEAGUE_SELECT_QUERY);
        if (error) throw error;
        return transformLeagues(data || []);
    } catch (err) {
        console.error('Erro fatal ao carregar ligas:', err);
        return [];
    }
};

function transformLeagues(data: any[]): League[] {
    return data.map(l => {
        const officialsList = l.officials || [];
        const referees = officialsList.filter((o: any) => o.type === 'referee').map((o: any) => ({ id: o.id, name: o.name, nickname: o.nickname, cpf: o.cpf, bankAccount: o.bank_account }));
        const tableOfficials = officialsList.filter((o: any) => o.type === 'table_official').map((o: any) => ({ id: o.id, name: o.name, nickname: o.nickname, cpf: o.cpf, bankAccount: o.bank_account }));

        return {
            id: l.id, 
            name: l.name, 
            slug: l.slug, 
            logoUrl: l.logo_url || '', 
            coverUrl: l.cover_url || '', 
            adminEmail: l.admin_email, 
            city: l.city || 'Cidade', 
            state: l.state || 'UF',
            referees,
            tableOfficials,
            championships: (l.championships || []).map((c: any) => {
                const clubs = (c.championship_clubs || []).map((cc: any) => cc.clubs).filter(Boolean).map((club: any) => ({
                    id: club.id, name: club.name, abbreviation: club.abbreviation, logoUrl: club.logo_url || '', whatsapp: club.whatsapp || '',
                    players: (club.players || []).map((p: any) => ({ id: p.id, name: p.name, position: p.position, goals: p.goals_in_championship || 0, photoUrl: p.photo_url || '', birthDate: p.birth_date || '', nickname: p.nickname || '', cpf: p.cpf || '' })),
                    technicalStaff: (club.technical_staff || []).map((ts: any) => ({ id: ts.id, name: ts.name, role: ts.role }))
                }));

                const matches = (c.matches || []).map((m: any) => {
                    const homeTeam = clubs.find((cl: any) => cl.id === m.home_team_id) || { id: m.home_team_id, name: 'Clube', abbreviation: 'CLU', logoUrl: '', players: [], technicalStaff: [] };
                    const awayTeam = clubs.find((cl: any) => cl.id === m.away_team_id) || { id: m.away_team_id, name: 'Clube', abbreviation: 'CLU', logoUrl: '', players: [], technicalStaff: [] };

                    const ref = officialsList.find((o: any) => o.id === m.referee_id)?.name;
                    const a1 = officialsList.find((o: any) => o.id === m.assistant1_id)?.name;
                    const a2 = officialsList.find((o: any) => o.id === m.assistant2_id)?.name;
                    const to = officialsList.find((o: any) => o.id === m.table_official_id)?.name;

                    return {
                        id: m.id, round: m.round, homeScore: m.home_score, awayScore: m.away_score, date: m.match_date, status: m.status, location: m.location || 'A definir',
                        homeTeam,
                        awayTeam,
                        referee: ref, assistant1: a1, assistant2: a2, tableOfficial: to,
                        refereeId: m.referee_id, assistant1Id: m.assistant1_id, assistant2Id: m.assistant2_id, tableOfficialId: m.table_official_id,
                        events: (m.match_events || []).map((e: any) => ({ type: e.type, player_id: e.player_id, playerName: '', minute: e.minute }))
                    };
                });

                const financials: ChampionshipFinancials = {
                    refereeFee: Number(c.referee_fee) || 0,
                    assistantFee: Number(c.assistant_fee) || 0,
                    tableOfficialFee: Number(c.table_official_fee) || 0,
                    fieldFee: Number(c.field_fee) || 0,
                    yellowCardFine: Number(c.yellow_card_fine) || 0,
                    redCardFine: Number(c.red_card_fine) || 0,
                    registrationFeePerClub: Number(c.registration_fee_per_club) || 0,
                    totalCost: (Number(c.referee_fee || 0) + (Number(c.assistant_fee || 0) * 2) + Number(c.table_official_fee || 0) + Number(c.field_fee || 0)) * matches.length
                };

                return { id: c.id, name: c.name, standings: [], financials, clubs, matches };
            })
        };
    });
}

