                        </div>

                        <button 
                            onClick={() => handleOAuthLogin('google')}
                            disabled={isLoading}
                            className="w-full bg-white hover:bg-gray-100 text-black font-black py-3 px-6 rounded-2xl flex items-center justify-center gap-4 transition-all disabled:opacity-50"
                        >
                            <svg className="w-5 h-5" viewBox="0 0 24 24">
                                <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                                <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                            </svg>
                            LOGIN COM GOOGLE
                        </button>

                        <button 
                            onClick={() => setShowHelp(true)}
                            className="text-[10px] text-red-500 hover:text-red-400 font-black uppercase tracking-tight block mx-auto underline italic"
                        >
                             Apareceu "403: access_denied"? Clique aqui para resolver!
                        </button>

                        <button 
                            onClick={() => setIsEmailMode(true)}
                            className="w-full bg-transparent hover:bg-white/5 text-gray-400 hover:text-white font-bold py-3 px-6 rounded-2xl flex items-center justify-center gap-4 transition-all text-xs border border-white/10"
                        >
                            USAR E-MAIL E SENHA
                        </button>

                    </div>
                ) : (
                    <form onSubmit={handleEmailAuth} className="space-y-4 animate-fade-in">
                        <div className="text-left mb-6">
                            <h2 className="text-white font-black text-xl uppercase italic">{isSignUp ? 'Criar Conta' : 'Entrar'}</h2>
                            <p className="text-gray-500 text-xs">Acesso rápido por e-mail</p>
                        </div>

                        <input 
                            type="email" 
                            placeholder="Seu e-mail" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full bg-[#2a2a2a] border-none rounded-2xl py-4 px-6 text-white focus:ring-2 focus:ring-green-500"
                            required
                        />
                        <input 
                            type="password" 
                            placeholder="Sua senha" 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full bg-[#2a2a2a] border-none rounded-2xl py-4 px-6 text-white focus:ring-2 focus:ring-green-500"
                            required
                        />

                        <button 
                            type="submit"
                            disabled={isLoading}
                            className="w-full bg-green-500 hover:bg-green-600 text-black font-black py-4 rounded-2xl transition-all shadow-xl shadow-green-500/20 disabled:opacity-50"
                        >
                            {isLoading ? 'CARREGANDO...' : (isSignUp ? 'CADASTRAR E ENTRAR' : 'ENTRAR NO APP')}
                        </button>

                        <div className="flex flex-col gap-3 mt-6">
                            <button 
                                type="button"
                                onClick={() => setIsSignUp(!isSignUp)}
                                className="text-green-500 font-bold text-xs uppercase hover:underline"
                            >
                                {isSignUp ? 'Já tenho uma conta' : 'Não tem conta? Clique aqui'}
                            </button>
                            <button 
                                type="button"
                                onClick={() => setIsEmailMode(false)}
                                className="text-gray-600 font-bold text-[10px] uppercase hover:text-white transition-colors"
                            >
                                Voltar
                            </button>
                        </div>
                    </form>
                )}

                <p className="mt-8 text-[10px] text-gray-700 font-black uppercase tracking-[0.4em]">
                    Powered by LigaFull
                </p>
            </div>
        </div>
    );
};

export default AuthWall;
